// Block (composition) — responsive article previews for editorial landing pages.
// Card, Link, and Avatar own their look; Grid and Stack own arrangement.
import type { ReactNode, Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Card } from "../components/Card";
import { Media } from "../components/Media";
import { Grid } from "../layouts/Grid";
import { Link } from "../components/Link";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./BlogPostGrid.css";

export interface BlogPostGridProps {
  posts: {
    id: string;
    title: string;
    excerpt?: string;
    author?: string;
    date?: string;
    image?: ReactNode;
    href?: string;
  }[];
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function BlogPostGrid({
  posts,
  columns = { small: 1, medium: 3 },
  className,
  ref,
}: BlogPostGridProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="Blog posts"
      columns={columns}
      gap="medium"
      className={className ? `sd-blogpostgrid ${className}` : "sd-blogpostgrid"}
    >
      {posts.map((post) => (
        <Card key={post.id} role="article">
          <Stack gap="medium" className="sd-blogpostgrid__content">
            {post.image && <Media className="sd-blogpostgrid__media">{post.image}</Media>}
            {/* The name and its supporting line are ONE unit, so they group at `x-small` while the
              card around them parts them two rungs looser — otherwise the same gap separates the
              pair as separates it from everything else. The media is a consumer's node, not a
              painted edge, so the parting law holds against it. */}
            <>
              <Stack gap="x-small" className="sd-blogpostgrid__heading">
                <h3 className="sd-blogpostgrid__title sd-type-title-medium">
                  {post.href ? <Link href={post.href}>{post.title}</Link> : post.title}
                </h3>
                {post.excerpt && (
                  <p className="sd-blogpostgrid__excerpt sd-type-body-medium">{post.excerpt}</p>
                )}
              </Stack>
            </>
            {(post.author || post.date) && (
              <Stack direction="row" align="center" gap="small" className="sd-blogpostgrid__meta-row">
                {/* With no avatar to lead the row, the date is text on the card's surface and takes
                    the inset (rule 8). After an avatar the author and date wrap in their own row, so
                    a wrapped date still starts after the avatar, not leading, at 0. */}
                {post.author ? (
                  <>
                    <Avatar size="small" alt={post.author}>
                      {post.author.charAt(0)}
                    </Avatar>
                    <Stack direction="row" align="center" gap="small" wrap>
                      <span className="sd-blogpostgrid__meta sd-type-caption-medium">
                        {post.author}
                      </span>
                      {post.date && (
                        <span className="sd-blogpostgrid__meta sd-type-caption-medium">{post.date}</span>
                      )}
                    </Stack>
                  </>
                ) : (
                  <>
                    <span className="sd-blogpostgrid__meta sd-type-caption-medium">{post.date}</span>
                  </>
                )}
              </Stack>
            )}
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* BlogPostGrid.css — .sd-blogpostgrid (Block)
   Arrangement only: fills its section and normalizes editorial text margins. */
.sd-blogpostgrid {
  width: 100%;
}

.sd-blogpostgrid__title,
.sd-blogpostgrid__excerpt,
.sd-blogpostgrid__meta {
  margin: 0;
}

.sd-blogpostgrid__meta {
  color: var(--sd-color-text-muted);
}

.sd-blogpostgrid__media {
  width: 100%;
}

.sd-blogpostgrid__excerpt {
  color: var(--sd-color-text-muted);
}
